    public static function organizaArregloPersonaCdgContable($arreglo)
    {
      //print_r($arreglo);  die;
      $nuevoArreglo        = array();
      $nuevoArregloPersona = array();
      $arreglocentroCosto  = array();
      $valortemp           = -1;
      $idcentroCosto  =$arreglo[0]['idcentrocosto'];
      $primeraVez       = true;
      foreach ($arreglo as $clave => $valor) {

        if ($valor['idcentrocosto'] != $valortemp) {
          if(!$primeraVez){
            array_push($nuevoArreglo, array('idcentrocosto' => $idcentroCosto, 'arraypersonas' => $nuevoArregloPersona));
            $nuevoArregloPersona = array();
            $idcentroCosto=$valor['idcentrocosto'];
            $primeraVez       = true;
          }
            $primeraVez       = false;
        }

        array_push($nuevoArregloPersona, $valor);
        if((count($arreglo)-1)==$clave){
          array_push($nuevoArreglo, array('idcentrocosto' => $idcentroCosto, 'arraypersonas' => $nuevoArregloPersona));
        }

        $valortemp = $valor['idcentrocosto'];
      }
      //print_r($nuevoArreglo);  die;
      return $nuevoArreglo;
    }

