    public static function obtenerConfigDadoIdEntidadOrdenadoPorCentroCosto($identidad)
    {

      $sql  = "SELECT
   conf_personacdgocontable.idestructura,
  conf_personacdgocontable.nombreapellido,
  conf_personacdgocontable.cdgocontable,
  conf_personacdgocontable.idpersona,
  conf_personacdgocontable.idpersonacdgocontable,
  dat_cargosocupados.idcentrocosto,
  dat_cargosocupados.idplantillanominal
FROM
  mod_nomina.dat_cargosocupados,
  mod_nomina.conf_personacdgocontable
WHERE
  conf_personacdgocontable.idpersona = dat_cargosocupados.idpersona AND
  conf_personacdgocontable.idestructura = dat_cargosocupados.identidad
  AND conf_personacdgocontable.idestructura=?
  ORDER BY dat_cargosocupados.idcentrocosto;";
      $mg   = Doctrine_Manager::getInstance();
      $conn = $mg->getCurrentConnection();
      return $conn->fetchAll($sql, array($identidad));
    }

